type I2C_Pin_Info is record
   Valid      : Boolean := False;
   Controller : I2C_Controller := I2C0;
end record;

type SPI_Pin_Info is record
   Valid      : Boolean := False;
   Controller : SPI_Controller := SPI0;
end record;

type UART_Pin_Info is record
   Valid      : Boolean := False;
   Controller : UART_Controller := UART0;
end record;

